(function(){
  function search(text, pattern, flags){
    flags=flags||'';
    if(!pattern) return {error:'请输入正则'};
    var f=''; if(flags.indexOf('i')>=0)f+='i'; if(flags.indexOf('m')>=0)f+='m'; if(flags.indexOf('g')>=0)f+='g'; if(flags.indexOf('u')>=0)f+='u';
    var re; try{ re=new RegExp(pattern, f); }catch(e){ return {error:'正则错误: '+e.message}; }
    var lines=String(text||'').split(/\r?\n/), res=[];
    if(re.global){
      for(var i=0;i<lines.length;i++){ var ln=lines[i], mm; re.lastIndex=0; while((mm=re.exec(ln))){ if(mm.index===re.lastIndex)re.lastIndex++; res.push({n:i+1, col:mm.index, text:ln, match:mm[0]}); } }
    } else {
      for(var i=0;i<lines.length;i++){ var m2=lines[i].match(re); if(m2) res.push({n:i+1, col:m2.index, text:lines[i], match:m2[0]}); }
    }
    return {value:res};
  }
  var API={search:search};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__RgForge__=API;
})();
